import os
from google.cloud import documentai_v1 as documentai

def extract_receipt_data(receipt_path: str):
    client = documentai.DocumentProcessorServiceClient()
    name = os.getenv('GOOGLE_APPLICATION_CREDENTIALS')
    project = 'projects/my-project-id'  # Replace with your actual project ID
    location = 'us'  # Or 'eu' depending on your Document AI location
    processor_id = 'projects/{}/locations/{}/processors/{}/processorVersions/1'.format(
        project.split('/')[1], location, 'invoice-parser'
    )

    with open(receipt_path, 'rb') as image:
        image_content = image.read()

    document = {'content': image_content, 'mime_type': 'image/png'}

    input_document = {'document': document}
    annotator = {
        'processor_name': processor_id,
        'annotation_specs': [],
    }

    request = {'document': input_document, 'annotator': annotator}
    response = client.process_document(request=request)

    # Extract merchant, tax, total, and items
    merchant = ''
    tax = 0.0
    total = 0.0
    items = []

    for entity in response.document.entities:
        if entity.display_name == 'Merchant':
            merchant = entity.normalized_value.text
        elif entity.display_name == 'Tax':
            tax = float(entity.normalized_value.text)
        elif entity.display_name == 'Total':
            total = float(entity.normalized_value.text)
        elif entity.display_name == 'ItemDescription':
            item = {'name': entity.normalized_value.text}
            if entity.parent_id:
                item['quantity'] = response.document.entities[entity.parent_id].normalized_value.text
                item['price'] = response.document.entities[entity.parent_id].normalized_value.text
            items.append(item)

    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }
